package workbench.kotlin.l01

import java.util.concurrent.CompletableFuture
import java.util.concurrent.Executor

/*
 * Do not edit this file. It is the same in src/main and src/solution.
 *
 * An inline function is copied into each caller when the CALLER is compiled. A test that called
 * retry() directly would keep a copy of the stub you started from and would never run your code.
 * So the tests call these ordinary functions instead. They are compiled together with Retry.kt,
 * so they always hold a fresh copy of your inline functions.
 */
object Callers {
    fun <T> retrying(maxAttempts: Int, shouldRetry: (Exception) -> Boolean, block: (Int) -> T): T =
        retry(maxAttempts, shouldRetry, block)

    fun <T> retryingAsync(executor: Executor, maxAttempts: Int, block: (Int) -> T): CompletableFuture<T> =
        retryAsync(executor, maxAttempts, block)

    /**
     * Tries each card in turn and returns the first one the gateway approves. A gateway exception
     * is retried, up to 3 attempts per card. `return card` is a non-local return: it leaves
     * firstApproved, not just the lambda. It compiles only while retry's block is inlined.
     */
    fun firstApproved(cards: List<String>, authorize: (String) -> String): String? {
        for (card in cards) {
            retry(maxAttempts = 3) { if (authorize(card) == "APPROVED") return card }
        }
        return null
    }
}
